<?php
declare(strict_types=1); require dirname(__DIR__).'/app/bootstrap.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
$q=Database::connection()->prepare("SELECT t.*,c.name company_name,o.name_ar origin_name,d.name_ar destination_name,(t.seats_total-COALESCE((SELECT SUM(b.passengers_count) FROM bookings b WHERE b.trip_id=t.id AND b.status='confirmed'),0)) seats_available FROM trips t JOIN companies c ON c.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE t.id=? AND t.is_published=1 AND t.status='available' AND c.status='active' AND t.departure_at>=NOW()");$q->execute([$id]);$trip=$q->fetch(); if(!$trip){http_response_code(404);exit('الرحلة غير موجودة أو لم تعد متاحة.');}
$error='';$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 Security::verifyCsrf(); $name=trim($_POST['name']??'');$phone=preg_replace('/[^0-9+]/','',$_POST['phone']??'');$count=max(1,min(20,(int)($_POST['passengers']??1)));$notes=trim($_POST['notes']??'');
 if(mb_strlen($name)<3 || strlen($phone)<8 || $count>(int)$trip['seats_available']){$error='تحقق من الاسم ورقم الهاتف وعدد المسافرين والمقاعد المتاحة.';}
 else try{
  $pdo=Database::connection();$pdo->beginTransaction();
  $lock=$pdo->prepare("SELECT id,seats_total,status,departure_at FROM trips WHERE id=? FOR UPDATE");$lock->execute([$id]);$locked=$lock->fetch();
  $used=$pdo->prepare("SELECT COALESCE(SUM(passengers_count),0) FROM bookings WHERE trip_id=? AND status='confirmed'");$used->execute([$id]);$available=(int)$locked['seats_total']-(int)$used->fetchColumn();
  if(!$locked || $locked['status']!=='available' || strtotime($locked['departure_at'])<time() || $count>$available){$pdo->rollBack();$error='لم تعد المقاعد المطلوبة متاحة. حدّث الصفحة للتحقق من المقاعد.';}
  else{
   $customer=$pdo->prepare("INSERT INTO customers(full_name,phone) VALUES(?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name)");$customer->execute([$name,$phone]);
   $cq=$pdo->prepare("SELECT id FROM customers WHERE phone=?");$cq->execute([$phone]);$customerId=(int)$cq->fetchColumn();
   $ref='ASM-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
   $ins=$pdo->prepare("INSERT INTO bookings(reference_code,trip_id,customer_id,passengers_count,status,customer_notes) VALUES(?,?,?,?, 'new',?)");$ins->execute([$ref,$id,$customerId,$count,$notes]);
   $pdo->commit();$message="طلب حجز جديد%0Aرقم الطلب: {$ref}%0Aالاسم: ".rawurlencode($name)."%0Aالهاتف: ".rawurlencode($phone)."%0Aالرحلة: ".rawurlencode($trip['origin_name'].' إلى '.$trip['destination_name'])."%0Aالتاريخ: ".rawurlencode($trip['departure_at'])."%0Aعدد المسافرين: {$count}";
   $success=['ref'=>$ref,'wa'=>'https://wa.me/'.($config['whatsapp']).'?text='.$message];
  }
 }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$config['debug']?$e->getMessage():'تعذر تسجيل الطلب حالياً. حاول مرة أخرى.';}
}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تفاصيل الرحلة | <?=e($config['name'])?></title><link rel="stylesheet" href="/assets/css/app.css"><style>.brand-mark img{width:100%;height:100%;object-fit:contain;border-radius:inherit}.detail-trip-image{width:100%;max-height:380px;object-fit:cover;border-radius:14px}.detail{max-width:900px;margin:auto}.detail-box{border:1px solid var(--line);border-radius:14px;padding:25px;margin-top:20px}.booking-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.booking-form .wide{grid-column:span 2}.alert{padding:15px;border-radius:9px;background:#eef7f2;color:#24624a}.alert-error{background:#fff1f1;color:#9b3333}@media(max-width:600px){.booking-form{grid-template-columns:1fr}.booking-form .wide{grid-column:auto}}</style></head><body><header class="site-header"><a class="brand" href="/"><span class="brand-mark"><?php if(!empty($config['logo'])):?><img src="<?=e($config['logo'])?>" alt="شعار الموقع"><?php else:?>م<?php endif;?></span><b><?=e($config['name'])?></b></a><a href="/trips.php">كل الرحلات</a></header><main class="section detail"><?php if(!empty($trip['image_path'])):?><img class="detail-trip-image" src="<?=e($trip['image_path'])?>" alt="صورة الحافلة"><?php endif;?><span class="eyebrow"><?=e($trip['company_name'])?></span><h1><?=e($trip['origin_name'])?> ← <?=e($trip['destination_name'])?></h1><?php if(($trip['trip_class']??'regular')==='vip'):?><span class="vip-badge">رحلة VIP</span><?php else:?><span class="regular-badge">رحلة عادية</span><?php endif;?><div class="detail-box"><div class="trip-meta"><span>تاريخ ووقت الذهاب</span><strong><?=e($trip['departure_at'])?></strong></div><div class="trip-meta"><span>موعد الوصول</span><strong><?=e($trip['arrival_at']?:'غير محدد')?></strong></div><div class="trip-meta"><span>نوع المركبة</span><strong><?=e($trip['vehicle_type']?:'حافلة')?></strong></div><div class="trip-meta"><span>المقاعد المتاحة (المؤكدة فقط)</span><strong><?=max(0,(int)$trip['seats_available'])?></strong></div><div class="trip-meta"><span>سعر التذكرة</span><strong><?=e(number_format((float)$trip['price'],2).' '.$trip['currency'])?></strong></div><?php if(!empty($trip['vehicle_description'])):?><p><b>تفاصيل الحافلة:</b><br><?=nl2br(e($trip['vehicle_description']))?></p><?php endif;?><?php if($trip['details']):?><p><?=nl2br(e($trip['details']))?></p><?php endif;?></div><div class="detail-box"><h2>طلب حجز</h2><?php if($success):?><div class="alert">تم تسجيل طلبك بنجاح. رقم الطلب: <b><?=e($success['ref'])?></b><p>الطلب جديد وغير مؤكد حتى تراجعه الإدارة.</p><a class="btn btn-gold" target="_blank" rel="noopener" href="<?=e($success['wa'])?>">فتح واتساب وإرسال التفاصيل</a></div><?php else:?><?php if($error):?><p class="alert alert-error"><?=e($error)?></p><?php endif;?><form method="post" class="booking-form"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><label>الاسم الكامل<input name="name" minlength="3" required></label><label>رقم الهاتف<input name="phone" inputmode="tel" minlength="8" required></label><label>عدد المسافرين<input type="number" name="passengers" min="1" max="20" value="1" required></label><label class="wide">ملاحظات<textarea name="notes" rows="3"></textarea></label><button class="btn btn-primary wide" type="submit">إرسال طلب الحجز</button></form><?php endif;?></div></main></body></html>